reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$update public.camporees set navigation_panels=array['program','budget','participants'] where id='20000000-0000-4000-8000-000000000001'$$,'admin can replace and add navigation panels');
select is((select navigation_panels from public.camporees where id='20000000-0000-4000-8000-000000000001'),array['program','budget','participants'],'navigation order is persisted');
select throws_ok($$update public.camporees set navigation_panels=array['inventory','inventory'] where id='20000000-0000-4000-8000-000000000001'$$,'23514',null,'duplicate panels rejected');
select throws_ok($$update public.camporees set navigation_panels=array['https://attacker.test'] where id='20000000-0000-4000-8000-000000000001'$$,'23514',null,'external destinations rejected');
select throws_ok($$update public.camporees set navigation_panels=array['inventory','tasks','program','budget'] where id='20000000-0000-4000-8000-000000000001'$$,'23514',null,'more than five total buttons rejected');
select throws_ok($$update public.camporees set navigation_panels=array[null::text] where id='20000000-0000-4000-8000-000000000001'$$,'23514',null,'null panel rejected');
select throws_ok($$update public.camporees set navigation_panels='[0:1]={inventory,inventory}'::text[] where id='20000000-0000-4000-8000-000000000001'$$,'23514',null,'nonstandard array bounds cannot bypass uniqueness');
select lives_ok($$update public.camporees set navigation_panels='{}' where id='20000000-0000-4000-8000-000000000001'$$,'admin can remove all optional panels');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
with changed as (update public.camporees set navigation_panels=array['tasks'] where id='20000000-0000-4000-8000-000000000001' returning id) select is(count(*),0::bigint,'viewer cannot configure navigation') from changed;
reset role;
update public.organization_members set role='editor' where organization_id='00000000-0000-4000-8000-000000000001' and user_id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
with changed as (update public.camporees set navigation_panels=array['tasks'] where id='20000000-0000-4000-8000-000000000001' returning id) select is(count(*),0::bigint,'editor cannot configure navigation') from changed;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000005',true);
with changed as (update public.camporees set navigation_panels=array['tasks'] where id='20000000-0000-4000-8000-000000000001' returning id) select is(count(*),0::bigint,'another organization admin cannot configure navigation') from changed;
reset role;
